/**
 * Migrations: generated by drizzle-kit into one folder per dialect
 * under `migrations/`, applied by Drizzle's stock migrator inside a
 * transaction on every start. On SQLite the file is snapshotted first when
 * anything is pending. After the run every expected table must exist.
 */
import { migrate as migratePostgres } from "drizzle-orm/bun-sql/postgres/migrator";
import { migrate as migrateSqlite } from "drizzle-orm/bun-sqlite/migrator";
import type { Connection } from "./connection.ts";
import {
  listTables,
  migrationsTable,
  raaqebTables,
  recordedMigrations,
} from "./inspect.ts";
import { localMigrations, migrationsFolder } from "./migrationfiles.ts";
import { snapshotSqlite } from "./sqlite.ts";

export type MigrateResult =
  | { ok: true; applied: string[]; snapshot: string | undefined }
  | { ok: false; migration: string | undefined; message: string };

export interface MigrateOptions {
  /** The folder holding one migrations folder per dialect; the source tree's by default. */
  migrations?: string;
  /** The clock, for the snapshot name. */
  now?: () => number;
}

/** The names of the migrations the database has recorded, in order; none when it has no record. */
export async function appliedMigrations(
  connection: Connection
): Promise<string[]> {
  const present = await listTables(connection);
  return present.includes(migrationsTable)
    ? await recordedMigrations(connection)
    : [];
}

/** Snapshots (SQLite, when pending), migrates in a transaction, verifies the tables. */
export async function migrateDatabase(
  connection: Connection,
  options: MigrateOptions = {}
): Promise<MigrateResult> {
  const applied = new Set(await appliedMigrations(connection));
  const pending = (
    await localMigrations(connection.backend, options.migrations)
  ).filter((name) => !applied.has(name));
  const [migration] = pending;
  let snapshot: string | undefined;
  if (migration !== undefined && connection.backend === "sqlite") {
    try {
      snapshot = await snapshotSqlite(
        connection,
        migration,
        (options.now ?? Date.now)()
      );
    } catch {
      return {
        message: `cannot take the snapshot before migration ${migration}; the database is untouched (snapshots/ in the data directory must be a writable folder)`,
        migration,
        ok: false,
      };
    }
  }
  if (migration !== undefined) {
    try {
      await runMigrator(connection, options.migrations);
    } catch {
      // The stock migrator rolls the whole batch back, so the first pending is
      // named. Its record table is created outside the transaction and stays.
      return {
        message: `migration ${migration} failed and was rolled back; nothing of it was applied${snapshot ? ", and a snapshot was taken first" : ""}`,
        migration,
        ok: false,
      };
    }
  }
  const present = await listTables(connection);
  const missing = raaqebTables.find((name) => !present.includes(name));
  if (missing) {
    return {
      message: `the database is missing the table ${missing} after migrating`,
      migration: undefined,
      ok: false,
    };
  }
  return { applied: pending, ok: true, snapshot };
}

async function runMigrator(
  connection: Connection,
  root: string | undefined
): Promise<void> {
  if (connection.backend === "sqlite") {
    migrateSqlite(connection.db, {
      migrationsFolder: migrationsFolder("sqlite", root),
    });
    return;
  }
  await migratePostgres(connection.db, {
    migrationsFolder: migrationsFolder("postgres", root),
    migrationsSchema: "public",
  });
}
